-- Recorded courses built from a YouTube video: lessons that play a time range of the source
-- video, the schedule settings on the course, and a per-day discussion board.
-- Generated by prisma migrate diff (additive only) + constraints and RLS below.

-- AlterEnum
ALTER TYPE "ContentType" ADD VALUE 'YOUTUBE';

-- AlterTable
ALTER TABLE "courses" ADD COLUMN     "schedule_config" JSONB,
ADD COLUMN     "source_duration_seconds" INTEGER,
ADD COLUMN     "source_video_id" TEXT;

-- AlterTable
ALTER TABLE "lessons" ADD COLUMN     "end_second" INTEGER,
ADD COLUMN     "start_second" INTEGER;

-- CreateTable
CREATE TABLE "discussion_posts" (
    "id" UUID NOT NULL,
    "tenant_id" UUID NOT NULL,
    "module_id" UUID NOT NULL,
    "user_id" UUID NOT NULL,
    "parent_id" UUID,
    "body" TEXT NOT NULL,
    "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "discussion_posts_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "discussion_posts_module_id_created_at_idx" ON "discussion_posts"("module_id", "created_at");

-- AddForeignKey
ALTER TABLE "discussion_posts" ADD CONSTRAINT "discussion_posts_module_id_fkey" FOREIGN KEY ("module_id") REFERENCES "modules"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "discussion_posts" ADD CONSTRAINT "discussion_posts_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "discussion_posts" ADD CONSTRAINT "discussion_posts_parent_id_fkey" FOREIGN KEY ("parent_id") REFERENCES "discussion_posts"("id") ON DELETE CASCADE ON UPDATE CASCADE;


-- A YOUTUBE lesson always carries a valid, non-empty range; other lesson types never do.
ALTER TABLE "lessons" ADD CONSTRAINT "lessons_youtube_range" CHECK (
  ("start_second" IS NULL AND "end_second" IS NULL)
  OR ("start_second" >= 0 AND "end_second" > "start_second")
);
-- YouTube video ids are exactly 11 URL-safe characters.
ALTER TABLE "courses" ADD CONSTRAINT "courses_source_video_id_format" CHECK ("source_video_id" IS NULL OR "source_video_id" ~ '^[A-Za-z0-9_-]{11}$');
ALTER TABLE "courses" ADD CONSTRAINT "courses_source_duration_positive" CHECK ("source_duration_seconds" IS NULL OR "source_duration_seconds" > 0);
ALTER TABLE "discussion_posts" ADD CONSTRAINT "discussion_posts_body_length" CHECK (char_length("body") BETWEEN 1 AND 2000);

-- RLS on the new tenant-owned table (same policy as 20261022000001_enable_rls).
ALTER TABLE "discussion_posts" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "discussion_posts" FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation ON "discussion_posts";
CREATE POLICY tenant_isolation ON "discussion_posts"
  USING (tenant_id = app_current_tenant_id())
  WITH CHECK (tenant_id = app_current_tenant_id());
